%[text] # refineTerminalResistanceData sample script
%[text] Run the function without any arguments. It uses default inputs and returns a result.
data = HighVoltageBatteryTool1.refineTerminalResistanceData;
head(data, 3) %[output:7120cf06]
tail(data, 3) %[output:3bcd9410]
disp(data.Properties.CustomProperties.TerminalResistanceTemperature) %[output:2da9c17b]
%%
%[text] Assume you have OCV data measured at different temperatures.
Temp = simscape.Value([0, 25, 60], "degC");
SOC_data = [0; 0.05; 0.15; 0.4; 0.8; 1];
TerminalResistance_data = simscape.Value( ...
  [0.47 0.17 0.13; 0.45 0.12 0.005; 0.218 0.072 0.04; 0.101 0.053 0.037; 0.086 0.044 0.03; 0.1 0.033 0.024], ...
  "Ohm");
%[text] Refine the data.
SOC_refine_interval = 0.01;

data = HighVoltageBatteryTool1.refineTerminalResistanceData( ...
  Temperature = Temp, ...
  SOC = SOC_data, ...
  SOCInterval = SOC_refine_interval, ...
  TerminalResistance = TerminalResistance_data );

r0Temp = data.Properties.CustomProperties.TerminalResistanceTemperature;

fig = figure; %[output:61660f17]
ax = axes(fig); %[output:61660f17]
hold(ax, "on") %[output:61660f17]
plot(ax, data.SOC, value(data.TerminalResistance)); %[output:61660f17]
scatter(ax, SOC_data, value(TerminalResistance_data)); %[output:61660f17]
grid(ax, "on"); %[output:61660f17]
xlabel(ax, "State of Charge"); %[output:61660f17]
ylabel(ax, "Terminal resistance (" + string(unit(data.TerminalResistance)) + ")"); %[output:61660f17]
title(ax, "Terminal resistance vs SOC at different temperatures"); %[output:61660f17]
leg = legend(ax, string(value(r0Temp)), Location="best"); %[output:61660f17]
title(leg, "Temperature (" + string(unit(r0Temp)) + ")") %[output:61660f17]
